CREATE MATERIALIZED VIEW silver.session_minute_state_mv TO silver.session_minute_state (`minute_bucket` DateTime('UTC'), `content_id` Int64, `video_session_id` FixedString(64), `user_id` FixedString(64), `platform` LowCardinality(String), `country` LowCardinality(String), `app_version` LowCardinality(String), `player_version` LowCardinality(String), `audio_languages` AggregateFunction(groupUniqArray, String), `subtitle_languages` AggregateFunction(groupUniqArray, String), `session_start_epoch` AggregateFunction(any, DateTime64(3, 'UTC')), `title` AggregateFunction(any, String), `video_type` AggregateFunction(any, String), `category` AggregateFunction(any, String), `show_name` AggregateFunction(any, String), `latest_event_type` AggregateFunction(argMax, String, DateTime64(3, 'UTC')), `latest_event` AggregateFunction(argMax, String, DateTime64(3, 'UTC')), `last_event_ts` SimpleAggregateFunction(max, DateTime64(3, 'UTC')), `is_active` AggregateFunction(argMax, UInt8, DateTime64(3, 'UTC'))) AS SELECT toStartOfMinute(event_timestamp) AS minute_bucket, content_id, video_session_id, user_id, platform, country, app_version, player_version, groupUniqArrayState(audio_language) AS audio_languages, groupUniqArrayState(subtitle_language) AS subtitle_languages, anyState(session_start_epoch) AS session_start_epoch, anyState(dictGetOrDefault('bronze.content_dict', 'title', content_id, 'unknown')) AS title, anyState(dictGetOrDefault('bronze.content_dict', 'video_type', content_id, 'unknown')) AS video_type, anyState(dictGetOrDefault('bronze.content_dict', 'category', content_id, 'unknown')) AS category, anyState(dictGetOrDefault('bronze.content_dict', 'show_name', content_id, 'unknown')) AS show_name, argMaxState(event_type, event_timestamp) AS latest_event_type, argMaxState(event, event_timestamp) AS latest_event, maxSimpleState(event_timestamp) AS last_event_ts, argMaxState(toUInt8((event IN ('VideoSessionStart', 'Play', 'network-bandwidth', 'AppForegrounded', 'resume', 'Seek', 'network-change', 'download_asset_played', 'upshift', 'dropped-frames', 'video-resize', 'buffer-health', 'network-activity', 'BufferStart', 'video_forward', 'BufferEnd', 'video_rewind', 'next_video_click', 'download_asset_play_stop', 'AdSkipTrueView', 'speed-change', 'speed-pause', 'speed-resume', 'audio-language', 'subtitle-language', 'download_initiated', 'download_completed', 'downshift', 'go_live_click', 'golive', 'preroll-disabled', 'video_quality_change', 'AdBufferEnd', 'AdBufferStart', 'chromecast_clicked', 'AdResume', 'chromecast_started', 'preview_watched', 'download_deleted', 'download_resumed', 'premium_button_click'))), event_timestamp) AS is_active FROM bronze.ott_events GROUP BY minute_bucket, content_id, video_session_id, user_id, platform, country, app_version, player_version